1	import { afterAll, beforeAll, describe, expect, it } from "vitest";
2	import { isNavigable, seaMap } from "@pirate-sea-race/content";
3	import { encounterRules } from "@pirate-sea-race/content/encounters";
4	import { defaultDuelConfig, DUEL_INPUT, findMove } from "@pirate-sea-race/simulation/duel";
5	import { checkFruitState, fruitRules, kitDescriptions } from "@pirate-sea-race/simulation/fruits";
6	import { Buttons, FruitMessageType, MAX_INSPECT_FRUIT_PER_SECOND } from "@pirate-sea-race/protocol";
7	import { startGameServer, type RunningGameServer } from "@pirate-sea-race/server";
8	import { HeadlessClient, ImpairmentProxy, sleep, type Movement } from "@pirate-sea-race/test-tools";
9	import { containsText, HOLD_E, openWater, playersAt, roomOf, startThroughLobby, tracker, until, type Seat } from "./seaDuelSetup.js";
10	import { tuned } from "./rubbingsSetup.js";
11	
12	/**
13	 * §9's fruit in the match room: four pedestals, one at each regular island's highest-id dock, dealt from the fruit's
14	 * own seed (pinned here, test-only: Ember on Palm Key and Mist Cay, Smoke on Ember Rock and Old Stones). A player
15	 * moored there inspects (F) and holds F for three seconds to eat; releasing, casting off, a grapple's reservation or a
16	 * disconnect interrupts it; the kit then goes into every duel at sea the player fights. Players drive it as a browser
17	 * does: E to moor, the input's fruit button held, the inspect message, J to grapple. Every test's rooms check the
18	 * ledger's and the room's invariants after every world tick (`tracker`), and the fruit state's own here.
19	 */
20	let server: RunningGameServer;
21	let endpoint: string;
22	
23	const FRUITS = ["ember", "smoke", "smoke", "ember"] as const;
24	
25	beforeAll(async () => {
26	  server = await startGameServer({ port: 0, host: "127.0.0.1", handleSignals: false, testPlacement: true, matchTuning: tuned({ testFruits: FRUITS, testHooks: true }) });
27	  endpoint = `http://127.0.0.1:${server.port}`;
28	});
29	
30	afterAll(async () => {
31	  await server.close();
32	});
33	
34	/** Each island's pedestal dock: its highest-id dock. */
35	const pedestalDock = (island: number) => seaMap.docks.filter((dock) => dock.island === island).at(-1)!;
36	const PALM = pedestalDock(0);
37	const EMBER_ROCK = pedestalDock(1);
38	const MIST = pedestalDock(3);
39	const EAT_TICKS = fruitRules.eatTicks;
40	/** Holding F (the input's fruit button), no throttle. */
41	const HOLD_F: Movement = { moveX: 0, moveY: 0, buttons: Buttons.Fruit };
42	
43	/** A heading of 64 (0 east, clockwise) from one tile toward another. */
44	function headingToward(from: Seat, to: { tileX: number; tileY: number }): number {
45	  return (Math.round((Math.atan2(to.tileY - from.tileY, to.tileX - from.tileX) / (2 * Math.PI)) * 64) + 64) % 64;
46	}
47	
48	/** Open water `distance` tiles from a dock, in a straight clear line from it, facing the dock (a grapple's aim). */
49	function seatOff(dock: { tileX: number; tileY: number }, distance: number): Seat {
50	  for (const [dx, dy] of [
51	    [-1, 0],
52	    [1, 0],
53	    [0, -1],
54	    [0, 1],
55	  ] as const) {
56	    const at = { tileX: dock.tileX + dx * distance, tileY: dock.tileY + dy * distance, heading: 0 };
57	    if (!isNavigable(seaMap, at.tileX, at.tileY) || !openWater(at, { ...dock, heading: 0 })) continue;
58	    return { ...at, heading: headingToward(at, dock) };
59	  }
60	  throw new Error(`no open water ${distance} tiles off dock ${dock.tileX},${dock.tileY}`);
61	}
62	
63	/** Moors a player at a dock: placed on it, then E held until the ship is moored. */
64	async function moor(client: HeadlessClient, dock: { id: number; tileX: number; tileY: number }): Promise<void> {
65	  await client.placeShip(endpoint, { tileX: dock.tileX, tileY: dock.tileY, heading: 0 });
66	  await client.holdUntil(HOLD_E, () => client.ship()?.dock === dock.id, 5000);
67	}
68	
69	/** Inspects the pedestal where the player is moored and resolves with the inspection it received. */
70	async function inspect(client: HeadlessClient) {
71	  const before = client.inspections.length;
72	  client.inspectFruit();
73	  await client.waitFor(() => client.inspections.length > before, 3000);
74	  return client.inspections.at(-1)!;
75	}
76	
77	/** Keeps sending a movement until `predicate` holds, without letting go after (unlike `holdUntil`). */
78	async function keepUntil(client: HeadlessClient, movement: Movement, predicate: () => boolean, timeoutMs = 5000): Promise<void> {
79	  const deadline = Date.now() + timeoutMs;
80	  while (!predicate()) {
81	    if (Date.now() > deadline) throw new Error(`condition not met within ${timeoutMs} ms`);
82	    client.sendInput(movement);
83	    await sleep(50);
84	  }
85	}
86	
87	/** A fruit tracker too: every room dealt the pinned fruit (test-only), and its fruit state stays consistent. */
88	function fruitTracker(onTestFinished: (fn: () => Promise<void>) => void) {
89	  const track = tracker(onTestFinished);
90	  const rooms = new Set<ReturnType<typeof roomOf>>();
91	  onTestFinished(async () => {
92	    for (const room of rooms) {
93	      expect(room.fruitState.pedestals.map((pedestal) => pedestal.kit)).toEqual([...FRUITS]);
94	      expect(checkFruitState(room.fruitState)).toEqual([]);
95	    }
96	  });
97	  return (client: HeadlessClient) => {
98	    track(client);
99	    rooms.add(roomOf(client));
100	  };
101	}
102	
103	/** Holds F until the player's kit is `kit`, and resolves with the world ticks the channel took (start to meal). */
104	async function eat(client: HeadlessClient, kit: string): Promise<number> {
105	  const room = roomOf(client);
106	  let startTick: number | undefined;
107	  const watch = setInterval(() => {
108	    startTick ??= room.fruitState.channels.find((channel) => channel.playerId === client.sessionId)?.startTick;
109	  }, 2);
110	  try {
111	    await client.holdUntil(HOLD_F, () => client.fruitView()?.kit === kit, 8000);
112	  } finally {
113	    clearInterval(watch);
114	  }
115	  const meal = room.fruitState.meals.find((each) => each.playerId === client.sessionId)!;
116	  return meal.tick - startTick! + 1;
117	}
118	
119	describe.concurrent("the fruit in the match room (§9)", () => {
120	  it("eats the fruit after three seconds of F at a full pedestal: the kit is the player's, and the pedestal is empty for everyone", async ({ onTestFinished }) => {
121	    const track = fruitTracker(onTestFinished);
122	    const watchSeat = seatOff(PALM, 4);
123	    const [eater, watcher] = (await playersAt(endpoint, [watchSeat, { ...watchSeat, tileY: watchSeat.tileY + 1 }], track)) as [HeadlessClient, HeadlessClient];
124	    const room = roomOf(eater);
125	    expect(room.pedestalSites.map((site) => site.dock)).toEqual([0, 1, 2, 3].map((island) => pedestalDock(island).id));
126	    // The watcher, at sea in sight of Palm Key's pedestal dock, sees its marker full, and no other island's.
127	    await watcher.waitFor(() => watcher.pedestalMarkers().some((marker) => marker.island === 0));
128	    expect(watcher.pedestalMarkers()).toEqual([{ id: "pedestal-0", island: 0, dock: PALM.id, full: true }]);
129	    expect(watcher.fruitView()).toMatchObject({ kit: "duelist", pedestal: "" });
130	
131	    await moor(eater, PALM);
132	    await eater.waitFor(() => eater.fruitView()?.pedestal === "full");
133	    expect(eater.fruitView()).toMatchObject({ kit: "duelist", fruitHeld: 0, fruitTotal: EAT_TICKS, fruitResult: "" });
134	    const { name, specials, advantage, vulnerability } = kitDescriptions.ember;
135	    expect(await inspect(eater)).toEqual({ island: 0, full: true, kit: "ember", name, specials: [...specials], advantage, vulnerability });
136	    // Inspecting is not eating: nothing is held, nothing changes.
137	    expect(room.fruitState.channels).toEqual([]);
138	
139	    // Halfway through, the status shows the progress.
140	    const halfway = eater.holdUntil(HOLD_F, () => (eater.fruitView()?.fruitHeld ?? 0) >= EAT_TICKS / 2, 5000);
141	    await halfway;
142	    const took = await eat(eater, "ember");
143	    // One continuous hold from the halfway point on would be 60 ticks; this one restarted after the release above.
144	    expect(took).toBe(EAT_TICKS);
145	    expect(eater.fruitView()).toMatchObject({ kit: "ember", pedestal: "empty", fruitHeld: 0, fruitResult: "eaten:ember" });
146	    expect(room.fruitState.meals).toEqual([expect.objectContaining({ playerId: eater.sessionId, pedestalId: "pedestal-0", kit: "ember" })]);
147	    // F kept down after the meal, at the pedestal just emptied: the meal stays the last result.
148	    await eater.hold(HOLD_F, 500);
149	    expect(eater.fruitView()?.fruitResult).toBe("eaten:ember");
150	    await watcher.waitFor(() => watcher.pedestalMarkers()[0]?.full === false);
151	    // Inspecting again says only that it is empty.
152	    expect(await inspect(eater)).toEqual({ island: 0, full: false });
153	    // Eating does not end protection or touch the ledger: the watcher, who ate nothing, is still the Duelist.
154	    expect(watcher.fruitView()?.kit).toBe("duelist");
155	  }, 40_000);
156	
157	  it("interrupts eating on release, casting off, a grapple's reservation and a disconnect, with the reason", async ({ onTestFinished }) => {
158	    const track = fruitTracker(onTestFinished);
159	    const proxy = await ImpairmentProxy.start(server.port);
160	    onTestFinished(async () => void (await proxy.close()));
161	    const grappleSeat = seatOff(EMBER_ROCK, 4);
162	    const [eater, attacker, dropper] = (await playersAt(endpoint, [seatOff(PALM, 4), grappleSeat, seatOff(MIST, 4)], track, {
163	      endpoints: [endpoint, endpoint, proxy.endpoint],
164	    })) as [HeadlessClient, HeadlessClient, HeadlessClient];
165	    const room = roomOf(eater);
166	    const status = (client: HeadlessClient) => room.state.status.get(client.sessionId)!;
167	
168	    // Releasing F part-way: the channel resets, and says so.
169	    await moor(eater, PALM);
170	    await eater.holdUntil(HOLD_F, () => (eater.fruitView()?.fruitHeld ?? 0) >= 10, 5000);
171	    await eater.waitFor(() => eater.fruitView()?.fruitResult === "interrupted:released" && eater.fruitView()?.fruitHeld === 0);
172	    expect(room.fruitState.meals).toEqual([]);
173	    // So does an input stream that stops with F held (§12: the held input lapses after 250 ms).
174	    await keepUntil(eater, HOLD_F, () => (eater.fruitView()?.fruitHeld ?? 0) >= 10);
175	    const lapsedFrom = eater.fruitView()!.fruitResultAt;
176	    await eater.waitFor(() => eater.fruitView()!.fruitResultAt > lapsedFrom && eater.fruitView()?.fruitResult === "interrupted:released", 3000);
177	    expect(room.fruitState.channels).toEqual([]);
178	
179	    // Casting off while holding F: the ship leaves the pedestal's dock, and the channel goes with it. Eating again first
180	    // clears the last result: a new attempt is under way.
181	    await keepUntil(eater, HOLD_F, () => (eater.fruitView()?.fruitHeld ?? 0) >= 10);
182	    expect(eater.fruitView()?.fruitResult).toBe("");
183	    const start = eater.fruitView()!.fruitResultAt;
184	    await keepUntil(eater, { ...HOLD_F, moveY: -1 }, () => eater.ship()?.dock === -1);
185	    // F still held at sea: no pedestal there, so the channel is gone.
186	    await keepUntil(eater, HOLD_F, () => (eater.fruitView()?.fruitResultAt ?? 0) > start && eater.fruitView()?.pedestal === "");
187	    expect(eater.fruitView()).toMatchObject({ fruitResult: "interrupted:released", fruitHeld: 0 });
188	    expect(room.fruitState.channels).toEqual([]);
189	    eater.sendInput({ moveX: 0, moveY: 0 });
190	
191	    // A grapple's reservation: the attacker grapples the eater, moored at Ember Rock's pedestal, mid-meal.
192	    await moor(eater, EMBER_ROCK);
193	    await attacker.waitFor(() => attacker.ship(eater.sessionId) !== undefined);
194	    let landed = false;
195	    const holding = keepUntil(eater, HOLD_F, () => landed, 15_000);
196	    await until(() => room.fruitState.channels.some((channel) => channel.playerId === eater.sessionId && channel.held >= 5), 3000, "the eater eating");
197	    // J pressed while the world is held, so the grapple's one-second windup starts on the next tick, inside the meal.
198	    room.pauseAfterTick(room.matchState.worldTick + 1);
199	    await until(() => room.worldPaused, 2000, "the pause");
200	    const held = room.fruitState.channels.find((channel) => channel.playerId === eater.sessionId)!.held;
201	    expect(held).toBeLessThan(EAT_TICKS - encounterRules.grapple.windupTicks - 5);
202	    attacker.tapGrapple();
203	    await sleep(150);
204	    room.resumeWorld();
205	    await until(() => room.encounterState.attempts.some((attempt) => attempt.attackerId === attacker.sessionId), 3000, "the grapple's windup");
206	    // The world held again right after the tick the grapple lands on: the reservation interrupted the meal on it.
207	    const landTick = room.encounterState.attempts.find((attempt) => attempt.attackerId === attacker.sessionId)!.landTick;
208	    room.pauseAfterTick(landTick);
209	    await until(() => room.worldPaused, 3000, "the landing");
210	    expect(room.encounterState.duels.some((duel) => duel.players.includes(eater.sessionId))).toBe(true);
211	    expect(status(eater)).toMatchObject({ fruitResult: "interrupted:reserved", fruitResultAt: landTick, fruitHeld: 0 });
212	    room.resumeWorld();
213	    landed = true;
214	    await holding;
215	    eater.sendInput({ moveX: 0, moveY: 0 });
216	    expect(room.fruitState.meals).toEqual([]);
217	    expect(room.encounterState.duels.some((duel) => duel.players.includes(eater.sessionId))).toBe(true);
218	    // Still at the pedestal's dock, but in a duel: the status offers no pedestal, and an inspection gets nothing.
219	    await eater.waitFor(() => eater.fruitView()?.pedestal === "");
220	    expect(eater.ship()?.dock).toBe(EMBER_ROCK.id);
221	    const inspected = eater.inspections.length;
222	    eater.inspectFruit();
223	    await sleep(300);
224	    expect(eater.inspections).toHaveLength(inspected);
225	
226	    // A disconnect: the dropper's channel is cancelled as a disconnect, which its status records for its return.
227	    await moor(dropper, MIST);
228	    let dropped = false;
229	    const dropping = keepUntil(dropper, HOLD_F, () => dropped, 30_000).catch(() => undefined);
230	    await until(() => room.fruitState.channels.some((channel) => channel.playerId === dropper.sessionId && channel.held >= 5), 3000, "the dropper eating");
231	    // The world held while the connection drops, so the drop is on record before the held input could lapse (§12: a
232	    // stream that stops is released after 250 ms, as above; a drop the room sees first is a disconnect).
233	    room.pauseAfterTick(room.matchState.worldTick + 1);
234	    await until(() => room.worldPaused, 2000, "the pause");
235	    proxy.sever({ refuse: true });
236	    await until(() => room.ledgerState.players.find((player) => player.id === dropper.sessionId)?.status === "disconnected", 3000, "the drop");
237	    room.resumeWorld();
238	    await until(() => status(dropper).fruitResult === "interrupted:disconnected", 3000, "the disconnect interrupting");
239	    expect(room.fruitState.channels.some((channel) => channel.playerId === dropper.sessionId)).toBe(false);
240	    dropped = true;
241	    await dropping;
242	    expect(room.fruitState.meals).toEqual([]);
243	  }, 45_000);
244	
245	  it("gives a contested fruit to the lowest id when both finish on one tick; the other is interrupted as taken", async ({ onTestFinished }) => {
246	    const track = fruitTracker(onTestFinished);
247	    const [a, b] = (await playersAt(endpoint, [seatOff(PALM, 4), seatOff(PALM, 5)], track)) as [HeadlessClient, HeadlessClient];
248	    const room = roomOf(a);
249	    await moor(a, PALM);
250	    await moor(b, PALM);
251	    // Both press F while the world is held after one tick, so both start on the next one and finish together.
252	    const paused = room.matchState.worldTick + 1;
253	    room.pauseAfterTick(paused);
254	    await until(() => room.worldPaused, 2000, "the pause");
255	    const [first, second] = a.sessionId < b.sessionId ? [a, b] : [b, a];
256	    let done = false;
257	    const holds = [first, second].map((client) => keepUntil(client, HOLD_F, () => done, 15_000));
258	    await sleep(300);
259	    // Held again right after the tick both finish on.
260	    room.pauseAfterTick(paused + EAT_TICKS);
261	    room.resumeWorld();
262	    await until(() => room.worldPaused && room.matchState.worldTick === paused + EAT_TICKS, 8000, "the finishing tick");
263	    const status = (client: HeadlessClient) => room.state.status.get(client.sessionId)!;
264	    expect(room.fruitState.meals).toEqual([expect.objectContaining({ playerId: first.sessionId, pedestalId: "pedestal-0", kit: "ember", tick: paused + EAT_TICKS })]);
265	    expect(status(first)).toMatchObject({ kit: "ember", fruitResult: "eaten:ember", fruitResultAt: paused + EAT_TICKS });
266	    expect(status(second)).toMatchObject({ kit: "duelist", fruitResult: "interrupted:taken", fruitResultAt: paused + EAT_TICKS });
267	    room.resumeWorld();
268	    done = true;
269	    await Promise.all(holds);
270	    for (const client of [first, second]) client.sendInput({ moveX: 0, moveY: 0 });
271	    await first.waitFor(() => first.fruitView()?.kit === "ember");
272	  }, 30_000);
273	
274	  it("refuses a fed player's further attempts and an empty pedestal, and keeps the kit through a lost duel", async ({ onTestFinished }) => {
275	    const track = fruitTracker(onTestFinished);
276	    // The eater never readies its arena: it loses the duel it is grappled into by forfeit.
277	    const [eater, other] = (await playersAt(endpoint, [seatOff(PALM, 4), seatOff(EMBER_ROCK, 4)], track, { clients: [{ autoReady: false }, {}] })) as [HeadlessClient, HeadlessClient];
278	    const room = roomOf(eater);
279	    await moor(eater, PALM);
280	    await eat(eater, "ember");
281	    // At Ember Rock's full pedestal, holding F is refused: this player has eaten.
282	    await moor(eater, EMBER_ROCK);
283	    await eater.holdUntil(HOLD_F, () => eater.fruitView()?.fruitResult === "refused:already-eaten", 5000);
284	    expect(eater.fruitView()?.kit).toBe("ember");
285	    expect(room.fruitState.pedestals.find((pedestal) => pedestal.id === "pedestal-1")!.eatenBy).toBeNull();
286	    // The other player at Palm Key's eaten pedestal: refused, it is empty.
287	    await moor(other, PALM);
288	    await other.holdUntil(HOLD_F, () => other.fruitView()?.fruitResult === "refused:empty", 5000);
289	    expect(other.fruitView()?.kit).toBe("duelist");
290	
291	    // The other grapples the eater; the eater forfeits by never readying, and waits to respawn: still Ember.
292	    await other.placeShip(endpoint, seatOff(EMBER_ROCK, 4));
293	    await other.waitFor(() => other.ship(eater.sessionId) !== undefined);
294	    other.tapGrapple();
295	    await eater.waitFor(() => eater.fruitView()?.kit === "ember" && eater.status()?.mode === "respawning", 15_000);
296	    expect(room.ledgerState.duels.at(-1)?.result).toMatchObject({ outcome: "win", winner: other.sessionId });
297	    // Out of the world while it waits, though its ship is still at Ember Rock's pedestal dock: F there does nothing.
298	    expect(room.matchState.ships.find((ship) => ship.id === eater.sessionId)?.dock).toBe(EMBER_ROCK.id);
299	    const last = room.state.status.get(eater.sessionId)!.fruitResultAt;
300	    await eater.hold(HOLD_F, 400);
301	    expect(room.state.status.get(eater.sessionId)!.fruitResultAt).toBe(last);
302	    expect(room.fruitState.channels).toEqual([]);
303	    await eater.waitFor(() => eater.status()?.mode === "sea", 10_000);
304	    expect(eater.fruitView()?.kit).toBe("ember");
305	    expect(room.fruitState.meals.map((meal) => meal.playerId)).toEqual([eater.sessionId]);
306	    // A player who leaves is no longer stepped: the match runs on, and the meal stays.
307	    await other.leave();
308	    const tick = room.matchState.worldTick;
309	    await until(() => room.matchState.worldTick > tick + 10, 3000, "the world ticking on");
310	    expect(room.flowState.end).toBeNull();
311	    expect(room.fruitState.meals.map((meal) => meal.playerId)).toEqual([eater.sessionId]);
312	  }, 45_000);
313	
314	  it("starts a sea duel with both kits on the server and both clients, the hashes agree, and the Ember player's flame bolt deals its damage", async ({ onTestFinished }) => {
315	    const track = fruitTracker(onTestFinished);
316	    const [ember, duelist] = (await playersAt(endpoint, [seatOff(PALM, 4), seatOff(PALM, 3)], track)) as [HeadlessClient, HeadlessClient];
317	    const room = roomOf(ember);
318	    await moor(ember, PALM);
319	    await eat(ember, "ember");
320	    // Back at sea, in grapple range of the Duelist, facing it.
321	    const at = seatOff(PALM, 4);
322	    const toward = seatOff(PALM, 3);
323	    await ember.placeShip(endpoint, { ...at, heading: headingToward(at, toward) });
324	    await duelist.placeShip(endpoint, toward);
325	    await ember.waitFor(() => ember.ship(duelist.sessionId) !== undefined);
326	    ember.tapGrapple();
327	    for (const client of [ember, duelist]) await client.waitFor(() => client.fighter.phase === "countdown", 5000);
328	    // The attacker's kit first, in the lobby both fighters read and in the server's frame-0 state.
329	    expect(room.seaDuelDiagnostics(ember.sessionId)!.kits).toEqual(["ember", "duelist"]);
330	    for (const client of [ember, duelist]) {
331	      expect(client.fighter.lobby?.kits).toBe("ember,duelist");
332	      expect(client.fighter.duel!.confirmedState.fighters.map((fighter) => fighter.kit)).toEqual(["ember", "duelist"]);
333	    }
334	
335	    // Ember presses U (special one) once the fight is on; the Duelist stands still.
336	    const cast = findMove(defaultDuelConfig.moveset, "flame-bolt-cast");
337	    const damage = cast.projectile!.damage;
338	    ember.fighter.play((frame) => (frame >= 20 && frame < 24 ? DUEL_INPUT.special1 : 0));
339	    const maxHealth = defaultDuelConfig.moveset.rules.maxHealth;
340	    for (const client of [ember, duelist]) await client.fighter.waitFor(() => client.fighter.confirmedState?.fighters[1].health === maxHealth - damage, 15_000);
341	    await until(() => room.seaDuelDiagnostics(ember.sessionId)!.frame > 150, 5000, "the fight going on");
342	    const server = room.seaDuelDiagnostics(ember.sessionId)!;
343	    expect(server.kits).toEqual(["ember", "duelist"]);
344	    // Both clients checked the server's per-frame hashes all along, with no desync.
345	    for (const client of [ember, duelist]) {
346	      expect(client.fighter.stats!.hashChecks).toBeGreaterThan(10);
347	      expect(client.fighter.stats!.desyncs).toBe(0);
348	    }
349	    expect(ember.fighter.confirmedState!.fighters[0].health).toBe(maxHealth);
350	  }, 45_000);
351	
352	  it("sends a pedestal's kit only to the player moored there who inspects it; other players see only full or empty, in sight; a kit reaches the opponent only in the duel's lobby (§16)", async ({ onTestFinished }) => {
353	    const track = fruitTracker(onTestFinished);
354	    const near = seatOff(PALM, 4);
355	    const [eater, onlooker, far] = (await playersAt(endpoint, [near, { ...near, tileY: near.tileY + 1 }, seatOff(MIST, 4)], track)) as [HeadlessClient, HeadlessClient, HeadlessClient];
356	    const room = roomOf(eater);
357	    const marks = { onlooker: onlooker.frameCount, far: far.frameCount, eater: eater.frameCount };
358	    await moor(eater, PALM);
359	    await inspect(eater);
360	    // An inspection at sea gets nothing: no pedestal there.
361	    onlooker.inspectFruit();
